from pwn import *

def main():
    server_address = 'pwn.chal.csaw.io'
    server_port = 8000

    inputs = ['1', '2']
    results = {}

    try:
        for user_input in inputs:
            io = remote(server_address, server_port)
            io.sendline(user_input)
            response = io.recv(timeout=5)
            results[user_input] = response.decode(errors='ignore')
            io.close()

        for key, value in results.items():
            print(f"Input {key}:\n{value}\n{'-' * 40}\n")

    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

